'use client';

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { supabase } from '@/lib/supabase';
import { getUpiConfigForTransaction } from '@/config/upiConfig';
import { useParams, useSearchParams, useRouter } from 'next/navigation';
import CheckoutForm from './checkout/CheckoutForm';
import OrderSummary from './checkout/OrderSummary';

// --- Types ---
interface PaymentState {
    step: 'billing' | 'payment' | 'verifying' | 'success' | 'failed' | 'expired' | 'manual_upload' | 'verified' | 'review_pending';
    amount: string;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    state: string;
    zip: string;
    country: string;
    utr: string;
    error: string;
    paymentMethod: 'upi' | 'card' | 'crypto';
}

interface ChallengePlan {
    id: string;
    name: string;
    price: number;
    label: string;
}

export default function PropFirmCheckout() {

    // --- Routing & Params ---
    const params = useParams();
    const searchParams = useSearchParams();
    const router = useRouter();  // No more duplicate require()
    const urlSessionId = params?.orderId as string;

    const queryAmount = searchParams.get('amount');
    const queryName = searchParams.get('name');
    const queryEmail = searchParams.get('email');

    // --- State Management ---
    const [state, setState] = useState<PaymentState>({
        step: 'billing',
        amount: '',
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        address: '',
        city: '',
        state: '',
        zip: '',
        country: 'India',
        utr: '',
        error: '',
        paymentMethod: 'upi'
    });

    const [sessionId, setSessionId] = useState<string>(urlSessionId || '');
    const [officialOrderId, setOfficialOrderId] = useState<string>('');
    const [timeLeft, setTimeLeft] = useState(15 * 60);
    const [termsAccepted, setTermsAccepted] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [selectedPlan, setSelectedPlan] = useState<string>('');

    // --- Configuration ---
    // UPI Config is fetched but mainly used in the next step (PaymentPageContent)
    const { vpa, merchantName } = getUpiConfigForTransaction(sessionId);

    const CHALLENGE_PLANS: ChallengePlan[] = [
        { id: '5k', name: '5K Challenge', price: 2499, label: '$5,000 Account' },
        { id: '10k', name: '10K Challenge', price: 4499, label: '$10,000 Account' },
        { id: '20k', name: '20K Challenge', price: 8499, label: '$20,000 Account' },
        { id: '100k', name: '100K Challenge', price: 29999, label: '$100,000 Account' },
    ];

    // --- Effects ---

    // 1. Initial Data Fetching
    useEffect(() => {
        if (queryAmount && queryName && queryEmail) {
            const names = queryName.split(' ');
            setState(prev => ({
                ...prev,
                amount: queryAmount,
                firstName: names[0] || '',
                lastName: names.slice(1).join(' ') || '',
                email: queryEmail
            }));

            const match = CHALLENGE_PLANS.find(p => p.price.toString() === queryAmount);
            if (match) setSelectedPlan(match.id);

        } else if (urlSessionId) {
            const fetchOrderDetails = async () => {
                try {
                    const { data } = await supabase
                        .from('transactions')
                        .select('*')
                        .or(`id.eq.${urlSessionId},session_id.eq.${urlSessionId}`)
                        .single();

                    if (data) {
                        const names = (data.customer_details?.name || '').split(' ');
                        setState(prev => ({
                            ...prev,
                            amount: data.amount.toString(),
                            firstName: names[0] || '',
                            lastName: names.slice(1).join(' ') || '',
                            email: data.customer_details?.email || '',
                            step: data.status === 'verified' ? 'verified' :
                                data.status === 'pending_payment' ? 'payment' : 'billing'
                        }));
                        if (data.order_id) setOfficialOrderId(data.order_id);

                        const match = CHALLENGE_PLANS.find(p => p.price.toString() === data.amount.toString());
                        if (match) setSelectedPlan(match.id);
                    }
                } catch (err) {
                    console.error("Error fetching order:", err);
                }
            };
            fetchOrderDetails();
            setSessionId(urlSessionId);
        }
    }, [queryAmount, queryName, queryEmail, urlSessionId]);

    // 2. Real-time Status Updates
    useEffect(() => {
        if (!sessionId) return;

        const subscription = supabase
            .channel(`public:transactions:session_id=eq.${sessionId}`)
            .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'transactions', filter: `session_id=eq.${sessionId}` }, (payload) => {
                const newStatus = payload.new.status;
                if (newStatus === 'verified') {
                    if (payload.new.order_id) setOfficialOrderId(payload.new.order_id);
                    setState(prev => ({ ...prev, step: 'verified' }));

                    // Receipt
                    axios.post('/api/send-receipt', {
                        utr: state.utr,
                        email: state.email,
                        name: `${state.firstName} ${state.lastName}`
                    }).catch(console.error);
                } else if (newStatus === 'rejected') {
                    setState(prev => ({ ...prev, step: 'failed', error: 'Verification failed.' }));
                }
            })
            .subscribe();

        return () => { supabase.removeChannel(subscription); };
    }, [sessionId]);

    // --- Handlers ---

    const handlePlanChange = (planId: string) => {
        const plan = CHALLENGE_PLANS.find(p => p.id === planId);
        if (plan) {
            setSelectedPlan(planId);
            setState(prev => ({ ...prev, amount: plan.price.toString() }));
        }
    };

    const handleStateChange = (key: string, value: string) => {
        setState(prev => ({ ...prev, [key]: value }));
    };

    const handlePlaceOrder = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!state.firstName || !state.email || !state.address || !state.city || !state.zip) {
            setState(prev => ({ ...prev, error: 'Please fill all fields.' }));
            return;
        }

        if (!termsAccepted) {
            setState(prev => ({ ...prev, error: 'You must accept the terms.' }));
            return;
        }

        setIsLoading(true);

        try {
            // Check existing
            const { data: existingData } = await supabase
                .from('transactions')
                .select('id')
                .eq('session_id', sessionId)
                .single();

            const orderPayload = {
                session_id: sessionId,
                amount: state.amount,
                utr: `TEMP-${sessionId}`,
                status: 'pending_payment',
                customer_details: {
                    name: `${state.firstName} ${state.lastName}`,
                    email: state.email,
                    phone: state.phone,
                    address: state.address,
                    city: state.city,
                    zip: state.zip,
                    country: state.country
                }
            };

            let dbError;
            if (existingData) {
                const { error } = await supabase.from('transactions').update(orderPayload).eq('session_id', sessionId);
                dbError = error;
            } else {
                const { error } = await supabase.from('transactions').insert([orderPayload]);
                dbError = error;
            }

            if (dbError) throw dbError;

            router.push(`/secure-checkout/${sessionId}?mode=payment`);

        } catch (err: any) {
            console.error('Order error:', err);
            setState(prev => ({ ...prev, error: err.message || 'Error processing order.' }));
            setIsLoading(false);
        }
    };

    const selectedPlanData = CHALLENGE_PLANS.find(p => p.id === selectedPlan);

    return (
        <div className="min-h-screen bg-[#F0F2F5] flex items-center justify-center p-4 font-sans text-slate-900">
            <div className="bg-white w-full max-w-6xl rounded-2xl shadow-xl overflow-hidden flex flex-col md:flex-row min-h-[600px]">

                {/* Left Side: Summary */}
                <OrderSummary
                    amount={state.amount}
                    planName={selectedPlanData?.name}
                    planLabel={selectedPlanData?.label}
                    officialOrderId={officialOrderId}
                />

                {/* Right Side: Form */}
                <div className="flex-1 p-8 md:p-12 overflow-y-auto">
                    <CheckoutForm
                        {...state}
                        plans={CHALLENGE_PLANS}
                        selectedPlan={selectedPlan}
                        termsAccepted={termsAccepted}
                        isLoading={isLoading}
                        onStateChange={handleStateChange}
                        onPlanChange={handlePlanChange}
                        onTermsChange={setTermsAccepted}
                        onSubmit={handlePlaceOrder}
                    />
                </div>

            </div>
        </div>
    );
}

