import React, { useState } from 'react';
import Image from 'next/image';
import { CheckCircle2, AlertCircle, ArrowRight, Check } from 'lucide-react';

// just passing the whole state down for now, easier than listing every prop
interface CheckoutFormProps {
    formData: any;
    plans: any[];
    selectedPlan: string;
    loading: boolean;
    setFormData: (key: string, value: string) => void;
    setPlan: (id: string) => void;
    submitOrder: (e: any) => void;
}

const CheckoutForm = ({
    formData,
    plans,
    selectedPlan,
    loading,
    setFormData,
    setPlan,
    submitOrder
}: CheckoutFormProps) => {

    const [agreed, setAgreed] = useState(false);

    const inputs = [
        { label: 'First Name', key: 'firstName', type: 'text', placeholder: 'John' },
        { label: 'Last Name', key: 'lastName', type: 'text', placeholder: 'Doe' },
        { label: 'Email', key: 'email', type: 'email', placeholder: 'john@example.com', full: true },
        { label: 'Phone', key: 'phone', type: 'tel', placeholder: '+91...', full: true },
        { label: 'Street Address', key: 'address', type: 'text', placeholder: '123 Trading St', full: true },
        { label: 'City', key: 'city', type: 'text', placeholder: 'Mumbai' },
        { label: 'Zip Code', key: 'zip', type: 'text', placeholder: '400001' },
    ];

    return (
        <form onSubmit={(e) => {
            if (!agreed) {
                alert("Please agree to T&C");
                e.preventDefault();
                return;
            }
            submitOrder(e);
        }} className="space-y-6 max-w-lg mx-auto pt-6">

            <div className="mb-8">
                <h3 className="font-bold text-lg mb-3 text-slate-800">Choose Account Size</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {plans.map(p => (
                        <div
                            key={p.id}
                            onClick={() => setPlan(p.id)}
                            className={`p-4 border rounded-xl cursor-pointer relative transition-all ${selectedPlan === p.id ? 'border-indigo-600 bg-indigo-50/50' : 'border-slate-200 hover:border-slate-300'}`}
                        >
                            <div className="font-semibold text-sm text-slate-700">{p.name}</div>
                            <div className="text-indigo-600 font-bold mt-1">₹{p.price.toLocaleString()}</div>
                            {selectedPlan === p.id && <CheckCircle2 className="absolute top-3 right-3 text-indigo-600" size={16} />}
                        </div>
                    ))}
                </div>
            </div>

            <h3 className="font-bold text-lg text-slate-800">Trader Details</h3>

            <div className="grid grid-cols-2 gap-4">
                {inputs.map((field) => (
                    <div key={field.key} className={field.full ? "col-span-2" : ""}>
                        <label className="text-xs font-semibold uppercase text-slate-500 mb-1 block">{field.label}</label>
                        <input
                            type={field.type}
                            value={formData[field.key] || ''}
                            onChange={(e) => setFormData(field.key, e.target.value)}
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-slate-900 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                            placeholder={field.placeholder}
                            required
                        />
                    </div>
                ))}

                <div className="col-span-2">
                    <label className="text-xs font-semibold uppercase text-slate-500 mb-1 block">Country</label>
                    <select
                        className="w-full border border-slate-300 rounded-lg p-2.5 text-slate-900 bg-white"
                        value={formData.country}
                        onChange={(e) => setFormData('country', e.target.value)}
                    >
                        <option value="India">India</option>
                        <option value="United States">United States</option>
                        <option value="United Kingdom">United Kingdom</option>
                        <option value="Canada">Canada</option>
                    </select>
                </div>
            </div>

            {formData.error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm flex items-center gap-2">
                    <AlertCircle size={16} />
                    {formData.error}
                </div>
            )}

            <div className="pt-4 border-t border-slate-100">
                <div className="flex items-start gap-3 mb-6">
                    <div
                        className={`w-5 h-5 rounded border flex items-center justify-center cursor-pointer mt-0.5 ${agreed ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'}`}
                        onClick={() => setAgreed(!agreed)}
                    >
                        {agreed && <Check size={14} className="text-white" />}
                    </div>
                    <p className="text-xs text-slate-500 leading-relaxed cursor-pointer" onClick={() => setAgreed(!agreed)}>
                        I confirm that I have read and agree to the <span className="text-indigo-600 underline">Terms of Service</span>.
                    </p>
                </div>

                <button
                    disabled={loading}
                    className="w-full bg-[#635BFF] hover:bg-[#544DCB] text-white font-bold py-3.5 rounded-xl transition-all shadow-lg shadow-indigo-200 disabled:opacity-70 flex justify-center items-center gap-2"
                >
                    {loading ? 'Processing...' : (
                        <>Get Funded Now <ArrowRight size={18} /></>
                    )}
                </button>

                {/* <div className="text-center mt-4 text-xs text-slate-400">
                    Test Mode Active
                </div> */}
            </div>

        </form>
    );
};

export default CheckoutForm;
